const nozzleIDs=['lift-FL','lift-FR','lift-RL','lift-RR','roll-FL','roll-FR','roll-RL','roll-RR','rear-boost','front-brake'];
const wheelIDs=['FL','FR','RL','RR'];
export const TELEMETRY_COLUMNS=['time_s','x_m','world_y_m','z_m','vx_mps','vy_mps','vz_mps','qx','qy','qz','qw','roll_deg','pitch_deg','heading_deg','wx_radps','wy_radps','wz_radps','mass_kg','pressure_bar','gas_temperature_K','gas_kg','sum_scalar_thrust_N','body_lift_demand_N','body_lift_actual_N','allocation_residual_normalized','suction_N','seal_quality','wheel_contacts','height_target_m','specific_force_g','energy_used_kWh','control_mode','supply_mode','maneuver',
  ...nozzleIDs.map(id=>id+'_actual_N'),
  ...nozzleIDs.map(id=>id+'_command_N'),'throttle_input','steer_toward_plus_X','brake_input','front_pair_input','rear_pair_input','motor_force_N','regen_force_N',...wheelIDs.flatMap(id=>['normal_N','brake_demand_N','longitudinal_N','lateral_N'].map(field=>id+'_'+field)),'body_slip_deg','road_wheel_steer_deg','mass_flow_kgps','effective_exhaust_mps','delivered_impulse_Ns','hover_seconds_estimate','steering_assist','traction_assist','air_stabilization_armed','air_stabilization_active','stabilization_mode','hold_active','hold_position_error_m','hold_attitude_error_deg','hold_speed_mps','hold_feasible','hold_wrench_residual','hold_target_x_m','hold_target_y_m','hold_target_z_m','hold_target_qx','hold_target_qy','hold_target_qz','hold_target_qw'];

export function telemetryRow(t){return [t.simTime,t.position.x,t.position.y,t.position.z,t.velocity.x,t.velocity.y,t.velocity.z,t.quaternion.x,t.quaternion.y,t.quaternion.z,t.quaternion.w,t.rollDeg,t.pitchDeg,t.headingDeg,t.angularVelocity.x,t.angularVelocity.y,t.angularVelocity.z,t.mass,t.pressureBar,t.gasTemperatureK,t.gasMass,t.thrustN,t.desiredWrench[1],t.achievedWrench[1],t.allocationError,t.suctionN,t.sealQuality,t.contactCount,t.targetAltitude,t.gLoad,t.energyUsedKWh,t.mode,t.supplyMode,t.maneuver?.name||'',...nozzleIDs.map(id=>t.nozzles.find(n=>n.id===id)?.force||0),...nozzleIDs.map(id=>t.nozzles.find(n=>n.id===id)?.command||0),t.driverInput?.throttle||0,t.driverInput?.steer||0,t.driverInput?.brake||0,t.driverInput?.frontJets||0,t.driverInput?.rearJets||0,t.motorForceN||0,t.regenForceN||0,...wheelIDs.flatMap(id=>{const w=t.wheelStates.find(w=>w.id===id)||{};return[w.normalLoadN||0,w.brakeDemandN||0,w.longitudinalForceN||0,w.lateralForceN||0];}),t.bodySlipDeg,t.steeringCentreDeg,t.massFlowKgS,t.effectiveExhaustVelocity,t.deliveredImpulseNs,t.hoverSecondsEstimate,Number(t.steeringAssist),Number(t.tractionAssist),Number(t.airStabilization),Number(t.stabilizationActive),t.stabilizationMode||'off',Number(t.holdActive),t.holdPositionError??'',t.holdAttitudeErrorDeg??'',t.holdSpeed??'',t.holdFeasible==null?'':Number(t.holdFeasible),t.holdWrenchResidual??'',t.holdPositionTarget?.x??'',t.holdPositionTarget?.y??'',t.holdPositionTarget?.z??'',t.holdQuaternionTarget?.x??'',t.holdQuaternionTarget?.y??'',t.holdQuaternionTarget?.z??'',t.holdQuaternionTarget?.w??''];}

export function telemetryCSV(rows,{params,events=[],date=new Date().toISOString()}={}){
  const cell=value=>typeof value==='number'?Number(value.toFixed(6)):String(value).includes(',')?'"'+String(value).replaceAll('"','""')+'"':value;
  return ['# Roadster Flight Lab 3.6 — engineering approximation; not OEM calibration','# Date '+date,'# Initial parameters '+JSON.stringify(params),'# Events '+JSON.stringify(events),TELEMETRY_COLUMNS.join(','),...rows.map(row=>row.map(cell).join(','))].join('\r\n');
}
